export function loadPlaylist(playlist: string[]): void {
    playlist.forEach((song) => {
        const audio = new Audio(song);
        audio.play();
    });
}

export function togglePlayback(): void {
    if (isPlaying) {
        pause();
    } else {
        resume();
    }
}

export function pause(): void {
    isPlaying = false;
    currentTime = 0;
    seekBar.value = 0;
    playButton.textContent = '▶';
}

export function resume(): void {
    isPlaying = true;
    const remainingTime = duration - currentTime;
    seekBar.max = duration;
    seekBar.value = currentTime;
    const interval = setInterval(() => {
        currentTime += 1;
        seekBar.value = currentTime;
        if (currentTime >= duration) {
            clearInterval(interval);
            currentTime = 0;
            seekBar.value = 0;
            playButton.textContent = '▶';
        }
    }, 1000);
}

export function seek(e: MouseEvent): void {
    const rect = seekBar.parentElement!.getBoundingClientRect();
    const offsetX = e.clientX - rect.left;
    const ratio = offsetX / rect.width;
    currentTime = Math.floor(duration * ratio);
    seekBar.value = currentTime;
    if (isPlaying) {
        const remainingTime = duration - currentTime;
        const interval = setInterval(() => {
            currentTime += 1;
            seekBar.value = currentTime;
            if (currentTime >= duration) {
                clearInterval(interval);
                currentTime = 0;
                seekBar.value = 0;
                playButton.textContent = '▶';
            }
        }, 1000);
    }
}

export function changeVolume(volume: number): void {
    volumeSlider.value = volume;
    volume = volume / 100;
    volumeSlider.style.background = `conic-gradient(#00d9ff 0% ${volume}%, #333 ${volume}% 100%)`;
    audio.volume = volume;
}

export function toggleMute(): void {
    if (isMuted) {
        isMuted = false;
        volumeSlider.value = 100;
        volumeSlider.style.background = `conic-gradient(#00d9ff 0% 100%, #333 0% 100%)`;
        audio.volume = 1;
        muteButton.textContent = '🔇';
    } else {
        isMuted = true;
        volumeSlider.value = 0;
        volumeSlider.style.background = `conic-gradient(#333 0% 100%, #333 0% 100%)`;
        audio.volume = 0;
        muteButton.textContent = '🔊';
    }
}

export function addSong(song: string): void {
    playlist.push(song);
    document.getElementById('playlistDisplay')!.innerHTML += `<div class="playlist-item">${song}</div>`;
}

export function removeSong(index: number): void {
    playlist.splice(index, 1);
    document.getElementById('playlistDisplay')!.querySelectorAll('.playlist-item')[index].remove();
}

