export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="player">
      <div class="album-art" style="background-image:url('https://via.placeholder.com/300')"></div>
      <div class="track-info">
        <h1 id="trackTitle">Track Name</h1>
        <p id="trackArtist">Artist Name</p>
        <div class="controls">
          <button id="playBtn" class="btn" onclick="togglePlayback()">▶ Play</button>
          <button id="prevBtn" class="btn" onclick="prevTrack()">◀ Prev</button>
          <button id="nextBtn" class="btn" onclick="nextTrack()">Next ▶</button>
          <div class="volume-slider">
            <input type="range" min="0" max="100" value="70" id="volumeSlider" oninput="adjustVolume(Number(this.value))">
            <span id="volumeDisplay">70%</span>
          </div>
        </div>
        <div class="progress-bar">
          <div class="progress-fill" id="progressFill"></div>
          <div class="progress-time" id="progressTime">0:00</div>
        </div>
      </div>
    </div>
    <div class="playlist">
      <h2>Playlist</h2>
      <div class="playlist-items">
        <div class="playlist-item" onclick="playTrack(0)">
          <span class="track-number">1</span>
          <span class="track-title">Track 1</span>
          <span class="track-duration">3:45</span>
        </div>
        <div class="playlist-item" onclick="playTrack(1)">
          <span class="track-number">2</span>
          <span class="track-title">Track 2</span>
          <span class="track-duration">4:20</span>
        </div>
        <div class="playlist-item" onclick="playTrack(2)">
          <span class="track-number">3</span>
          <span class="track-title">Track 3</span>
          <span class="track-duration">5:15</span>
        </div>
        <div class="playlist-item" onclick="playTrack(3)">
          <span class="track-number">4</span>
          <span class="track-title">Track 4</span>
          <span class="track-duration">3:50</span>
        </div>
        <div class="playlist-item" onclick="playTrack(4)">
          <span class="track-number">5</span>
          <span class="track-title">Track 5</span>
          <span class="track-duration">4:30</span>
        </div>
      </div>
    </div>
  `;

  const btnPlay = document.getElementById('playBtn');
  const btnPrev = document.getElementById('prevBtn');
  const btnNext = document.getElementById('nextBtn');
  const volumeSlider = document.getElementById('volumeSlider');
  const progressFill = document.getElementById('progressFill');
  const progressTime = document.getElementById('progressTime');

  let currentTrack = 0;
  let isPlaying = false;
  let audio: HTMLAudioElement;

  function togglePlayback() {
    isPlaying = !isPlaying;
    if (isPlaying) {
      btnPlay.textContent = '⏸ Pause';
      playTrack(currentTrack);
    } else {
      btnPlay.textContent = '▶ Play';
      pausePlayback();
    }
  }

  function playTrack(index: number) {
    currentTrack = index;
    if (isPlaying) {
      resumePlayback();
    } else {
      pausePlayback();
      loadTrack(index);
    }
  }

  function pausePlayback() {
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
  }

  function resumePlayback() {
    if (audio) {
      audio.play();
    }
  }

  function loadTrack(index: number) {
    const tracks = [
      { title: 'Track 1', artist: 'Artist 1', duration: 245, src: 'track1.mp3' },
      { title: 'Track 2', artist: 'Artist 2', duration: 250, src: 'track2.mp3' },
      { title: 'Track 3', artist: 'Artist 3', duration: 260, src: 'track3.mp3' },
      { title: 'Track 4', artist: 'Artist 4', duration: 240, src: 'track4.mp3' },
      { title: 'Track 5', artist: 'Artist 5', duration: 255, src: 'track5.mp3' },
    ];

    const track = tracks[index];
    if (track) {
      if (audio) {
        audio.src = track.src;
        audio.currentTime = 0;
        audio.volume = volumeSlider.value / 100;
        audio.play();
      }
      updateProgress(0, track.duration);
      updateTrackDisplay(track.title, track.artist);
    }
  }

  function updateProgress(current: number, total: number) {
    if (audio) {
      const fill = (current / total) * 100;
      progressFill.style.width = fill + '%';
      progressTime.textContent = formatTime(current) + ' / ' + formatTime(total);
    }
  }

  function formatTime(seconds: number) {
    const minutes = Math.floor(seconds / 60);
    const remaining = seconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(remaining).padStart(2, '0')}`;
  }

  function nextTrack() {
    currentTrack = (currentTrack + 1) % 5;
    playTrack(currentTrack);
  }

  function prevTrack() {
    currentTrack = (currentTrack - 1 + 5) % 5;
    playTrack(currentTrack);
  }

  function adjustVolume(volume: number) {
    if (audio) {
      audio.volume = volume / 100;
      volumeSlider.value = audio.volume * 100;
      document.getElementById('volumeDisplay')!.textContent = volume + '%';
    }
  }

  function updateTrackDisplay(title: string, artist: string) {
    document.getElementById('trackTitle')!.textContent = title;
    document.getElementById('trackArtist')!.textContent = artist;
  }
}

