export function handleInput(event: KeyboardEvent | MouseEvent): void {
    const inputType = event instanceof MouseEvent ? 'click' : 'keyboard';
    const key = (event instanceof MouseEvent ? (event as MouseEvent).button : event.key).toLowerCase();
    const actions = {
        play_pause: ['space', 'play', 'pause'],
        rewind: ['left', 'arrowleft'],
        forward: ['right', 'arrowright'],
        volume_down: ['down', 'arrowdown'],
        volume_up: ['up', 'arrowup'],
        mute: ['m', 'm'],
        next: ['n', 'arrowright'],
        previous: ['p', 'arrowleft'],
    };

    for (const [action, keys] of Object.entries(actions)) {
        if (keys.includes(key)) {
            switch (action) {
                case 'play_pause':
                    togglePlayback();
                    break;
                case 'rewind':
                    seek(-10);
                    break;
                case 'forward':
                    seek(10);
                    break;
                case 'volume_down':
                    changeVolume(Math.max(0, Math.min(100, parseInt(document.getElementById('volumeSlider')!.value) - 10)));
                    break;
                case 'volume_up':
                    changeVolume(Math.min(100, parseInt(document.getElementById('volumeSlider')!.value) + 10));
                    break;
                case 'mute':
                    toggleMute();
                    break;
                case 'next':
                    nextSong();
                    break;
                case 'previous':
                    previousSong();
                    break;
                default:
                    break;
            }
            return;
        }
    }
}

