export class MusicPlayerDataStore {
  private state: { songs: { title: string; artist: string; duration: number; played: boolean }[]; currentSongIndex: number; volume: number; isPlaying: boolean } = { songs: [], currentSongIndex: 0, volume: 100, isPlaying: false };
  private events: { type: 'state_changes' | 'song_played' | 'volume_changed' | 'play_pause' }[] = [];

  constructor() {}

  connectDb() {
    this.state.songs = [
      { title: 'Song 1', artist: 'Artist 1', duration: 300, played: false },
      { title: 'Song 2', artist: 'Artist 2', duration: 250, played: false },
      { title: 'Song 3', artist: 'Artist 3', duration: 350, played: false },
    ];
  }

  saveState(newState: { songs: { title: string; artist: string; duration: number; played: boolean }[]; currentSongIndex: number; volume: number; isPlaying: boolean }) {
    this.state = { ...this.state, ...newState };
    this.events.push({ type: 'state_changes', snapshot: { ...this.state } });
  }

  loadFromDb() {
    this.state.songs = [
      { title: 'Song 4', artist: 'Artist 4', duration: 200, played: true },
      { title: 'Song 5', artist: 'Artist 5', duration: 250, played: false },
      { title: 'Song 6', artist: 'Artist 6', duration: 300, played: true },
    ];
    this.state.currentSongIndex = 2;
    this.state.volume = 75;
    this.state.isPlaying = true;
  }

  getGameState() {
    return this.state;
  }

  playPause() {
    this.state.isPlaying = !this.state.isPlaying;
    this.events.push({ type: 'play_pause', snapshot: { ...this.state } });
  }

  volumeUp() {
    this.state.volume = Math.min(100, this.state.volume + 5);
    this.events.push({ type: 'volume_changed', snapshot: { ...this.state } });
  }

  volumeDown() {
    this.state.volume = Math.max(0, this.state.volume - 5);
    this.events.push({ type: 'volume_changed', snapshot: { ...this.state } });
  }

  nextSong() {
    this.state.currentSongIndex = (this.state.currentSongIndex + 1) % this.state.songs.length;
    this.events.push({ type: 'song_played', snapshot: { ...this.state } });
  }

  prevSong() {
    this.state.currentSongIndex = (this.state.currentSongIndex - 1 + this.state.songs.length) % this.state.songs.length;
    this.events.push({ type: 'song_played', snapshot: { ...this.state } });
  }
}

