export class AudioEngine {
  private audioContext: AudioContext | undefined;
  private audioSources: { [id: string]: AudioBufferSourceNode } = {};
  private audioBuffers: { [id: string]: AudioBuffer } = {};
  private currentTrack: number = 0;
  private volume: number = 0.5;
  private muted: boolean = false;

  constructor() {}

  async initAudioContext() {
    if (this.audioContext) return;
    try {
      this.audioContext = new AudioContext();
      console.log('Audio context initialized');
    } catch (error) {
      console.error('Error initializing audio context:', error);
    }
  }

  async loadAudioBuffer(id: string, src: string) {
    if (this.audioBuffers[id]) return;
    try {
      const response = await fetch(src);
      const arrayBuffer = await response.arrayBuffer();
      this.audioBuffers[id] = await this.audioContext?.decodeAudioData(arrayBuffer);
      console.log(`Loaded audio buffer: ${id}`);
    } catch (error) {
      console.error(`Error loading audio buffer ${id}:`, error);
    }
  }

  async playTrack(trackId: string) {
    if (!this.audioContext) return;
    try {
      const track = this.audioBuffers[trackId];
      if (!track) {
        console.error(`Track not found: ${trackId}`);
        return;
      }
      if (this.audioSources[trackId]) {
        this.audioSources[trackId].stop();
        delete this.audioSources[trackId];
      }
      const source = this.audioContext?.createBufferSource();
      source?.connect(this.audioContext?.destination);
      source?.buffer = track;
      source?.start();
      this.audioSources[trackId] = source;
      this.currentTrack = trackId;
      console.log(`Playing track: ${trackId}`);
    } catch (error) {
      console.error(`Error playing track ${trackId}:`, error);
    }
  }

  async pauseTrack() {
    if (!this.audioContext) return;
    try {
      if (this.audioSources[this.currentTrack]) {
        this.audioSources[this.currentTrack].stop();
      }
    } catch (error) {
      console.error('Error pausing track:', error);
    }
  }

  async resumeTrack() {
    if (!this.audioContext) return;
    try {
      if (this.audioSources[this.currentTrack]) {
        this.audioSources[this.currentTrack].resume();
      }
    } catch (error) {
      console.error('Error resuming track:', error);
    }
  }

  async stopAllTracks() {
    if (!this.audioContext) return;
    try {
      for (const source of Object.values(this.audioSources)) {
        if (source) source?.stop();
      }
      this.audioSources = {};
      this.currentTrack = null;
      console.log('All tracks stopped');
    } catch (error) {
      console.error('Error stopping tracks:', error);
    }
  }

  setVolume(volume: number) {
    this.volume = volume;
    if (this.audioContext) {
      this.audioContext?.masterGain?.gain?.value = volume;
    }
  }

  toggleMute() {
    this.muted = !this.muted;
    this.setVolume(this.muted ? 0 : this.volume);
  }

  shutdown() {
    this.stopAllTracks();
    this.audioContext?.close();
    this.audioContext = undefined;
    console.log('Audio engine shutdown');
  }
}
